import java.io.*;
import java.util.*;

public class A {
    private static List<Long> dataList, sumList;

    private static void computeSubsets(int index, long currentSum) {
        if (index == dataList.size()) {
            sumList.add(currentSum);
            return;
        }
        computeSubsets(index + 1, currentSum + dataList.get(index));
        computeSubsets(index + 1, currentSum);
    }

    private static boolean verifyCondition(long M, long W, long x) {
        if (x == M) return true;

        long totalX = x + M;
        while (totalX > 0) {
            if (totalX % W > 1) return false;
            totalX /= W;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] inputLine = br.readLine().split(" ");
        long W = Long.parseLong(inputLine[0]);
        long M = Long.parseLong(inputLine[1]);

        if (W == 2) {
            System.out.println("YES");
            return;
        }

        dataList = new ArrayList<>();
        dataList.add(1L);
        dataList.add(W);

        long val = W;
        final long MAX_LIMIT = (long) 1e10;

        while (true) {
            val *= W;
            if (val < 0 || val > MAX_LIMIT) break;
            dataList.add(val);
        }

        sumList = new ArrayList<>();
        computeSubsets(0, 0);

        boolean answerFlag = false;
        for (long candidateSum : sumList) {
            answerFlag |= verifyCondition(M, W, candidateSum);
            if (answerFlag) break;
        }

        System.out.println(answerFlag ? "YES" : "NO");
    }
}
